head.script:
scwin.trigger1_onclick = function(e) {
    dataList1.removeRows([0, 1, 2, 3, 4, 5]);
};
scwin._checkStyle = function() {
    var el = WebSquare.wUnit.getJq('#gridView1_body_tbody tr');
    var count = 0;
    for (var i = 0; i < el.length; i++) {
        if (el[i].style.display == "none") {
            count++;
        }
    }
    return count > 0;
}
scwin.checkVal = function() {
    return window.getComputedStyle(WebSquare.wUnit.getDomById($p.id + 'gridView1_scrollY_div')).getPropertyValue('overflow-y') == 'hidden';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Script 탭에서 scwin.trigger1_onclick 부분을 확인한다.
    //1. In the Script tab, check scwin.trigger1_onclick.
    //Verify 1. dataList1.removeRows( [0,1,2,3,4,5] );
    //Test step 2. 브라우저에서 removeRows 버튼을 클릭한다.
    //2. Click the removeRows button in your browser.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 6개의 row 가 삭제된다. (그전버전에서는 6개의 row가 삭제되나, 스크롤이 그대로 남아있는 현상이 발생함.)
    //2. Six rows are deleted. (In previous versions, 6 rows were deleted, but scrolling remained unchanged.)
    WebSquare.wUnit.addCommand("assert", "scwin._checkStyle()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 08-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
